row={'id':'slice08b-LPB-FH-BS-BANK-01-defined-regulatory-context','ticker':'LPB','securityId':q['securityId'],'metricId':'FH-BS-BANK-01','sourceAsOf':'2026-06-30','reviewedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'reviewer':'CODEX_DATA_PRODUCER_MACHINE_AND_SOURCE_IMAGE_REVIEW','rubricAuthority':authority,'evidence':evidence,'reviewerRationale':'The defined issuer disclosure establishes TT41/TT22 standalone scope, total CAR, regulatory capital composition, RWA/market/operational risk inputs, capital contingency planning, credit-growth allocation and periodic stress testing. Government article 6 establishes the published general floor and permits higher bank-specific requirements. TT14 transition terms explain why declared TT41 reporting must not be silently relabelled TT14/CET1. Internal numerical buffer, actual adverse-scenario capital results and any bank-specific higher minimum are not disclosed in these sources. Target NPL below 2.5% is a policy target, never the observed NPL. The 11.23% article claim remains an unexplained separate source-context discrepancy; it is not resolved into this defined 11.18% fact. No capital adequacy score, economic equivalence of article claims, or regulatory compliance conclusion is asserted.','confidence':'MEDIUM','confidenceMeaning':'SOURCE_AND_RUBRIC_CONTEXT_ONLY; MISSING_BUFFER_AND_STRESS_PARAMETERS_REMAIN','coverageStatus':'PARTIAL_RUBRIC_EVIDENCE','remainingRequiredContext':['BANK_SPECIFIC_MINIMUM_OR_GOVERNED_UNCERTAINTY_TREATMENT','NUMERICAL_MANAGEMENT_BUFFER_OR_GOVERNED_UNCERTAINTY_TREATMENT','ASSET_QUALITY_STRESS_CAPITAL_SENSITIVITY'],'canonicalOperandIds':[],'derivedAssessmentId':None,'score':None,'governanceStatus':'REVIEW_CANDIDATE','approvalReference':None}
